insert into public.entries (
  title, slug, scope, entry_type, era, start_year, end_year, date_is_approximate,
  location_name, summary, significance, origin_location, current_location,
  origin_coordinate_precision, current_coordinate_precision,
  origin_coordinate_source, current_coordinate_source, reviewed
) values
  ('Intramuros', 'intramuros', 'local', 'place', 'Spanish colonial', 1571, null, false, 'Manila, Metro Manila', 'Intramuros (lit. ''within the walls'' or ''inside the walls'' in Spanish) is the 0.67-square-kilometer (0.26 sq mi) historic walled area within the city of Manila, the capital of the Philippines. It is administered by the Intramuros Administration with the help of the city government of Manila.', 'Administrative and religious centre of Spanish Manila.', st_setsrid(st_makepoint(120.9736, 14.5939), 4326)::geography, null, 'area_centroid', null, 'https://intramuros.gov.ph/', null, false),
  ('Fort Santiago', 'fort-santiago', 'local', 'place', 'Spanish colonial', 1571, null, false, 'Intramuros, Manila', 'Fort Santiago (Spanish: Fuerte de Santiago; Filipino: Moóg ng Santiago), built in 1571, is a citadel or castle built by Spanish navigator and governor Miguel López de Legazpi for the newly established city of Manila in the Philippines. The defense fortress is located in Intramuros, the walled city of Manila. The fort is one of the most important historical sites in Manila.', 'Defensive citadel at the mouth of the Pasig River where José Rizal was imprisoned before his 1896 execution.', st_setsrid(st_makepoint(120.9716, 14.5956), 4326)::geography, null, 'approximate', null, 'https://www.wikidata.org/wiki/Q478181', null, false),
  ('San Agustin Church', 'san-agustin-church', 'local', 'place', 'Spanish colonial', 1607, null, false, 'Intramuros, Manila', 'The Archdiocesan Shrine of Our Lady of Consolation and Cincture, also known as the San Agustin Church (Filipino: Simbahan ng San Agustín) and Immaculate Conception Parish (Filipino: Parokya ng Kalinis-linisang Concepción), is a Roman Catholic church under the auspices of the Order of Saint Augustine located inside the historic walled city of Intramuros in Manila, Philippines.', 'Oldest stone church in the Philippines and part of the Baroque Churches of the Philippines UNESCO World Heritage Site. UNESCO World Heritage criteria (ii)(iv) (inscribed 1993): Brief synthesis The Baroque Churches of the Philippines is a serial inscription consisting of four Roman Catholic churches constructed between the 16thand the18th centuries in the Spanish period of the Philippines.', st_setsrid(st_makepoint(120.9722, 14.5934), 4326)::geography, null, 'approximate', null, 'https://data.unesco.org/explore/dataset/whc001/?q=677', null, false),
  ('Manila Cathedral', 'manila-cathedral', 'local', 'place', 'Spanish colonial / Postwar', 1571, null, false, 'Intramuros, Manila', 'The Minor Basilica and Metropolitan Cathedral of the Immaculate Conception, commonly known as the Manila Cathedral, is a Roman Catholic basilica and the cathedral of the Archdiocese of Manila. It is dedicated to the Blessed Virgin Mary of the Immaculate Conception, the principal patroness of the Philippines.', 'Seat of the Roman Catholic Archdiocese of Manila, rebuilt multiple times after earthquakes and World War II.', st_setsrid(st_makepoint(120.9736, 14.5915), 4326)::geography, null, 'exact', null, 'https://www.wikidata.org/wiki/Q773443', null, false),
  ('Rizal Park', 'rizal-park', 'local', 'place', 'Spanish colonial / American period', 1820, null, true, 'Ermita, Manila', 'Rizal Park, Luneta (Filipino: Liwasang Rizal, Luneta), also known as Rizal Park, Luneta Park, or simply Luneta, is a historic urban park located in Ermita, Manila, Philippines. It is one of the largest urban parks in the country, covering an area of 58 hectares (140 acres). The area now occupied by the park was known as Bagumbayan during the Spanish colonial period. It is adjacent to the historic walled city of Intramuros.', 'Historic Bagumbayan field where José Rizal was executed in 1896 and Philippine independence was proclaimed in 1946.', st_setsrid(st_makepoint(120.9783, 14.5825), 4326)::geography, null, 'area_centroid', null, 'http://www.nationalparks.ph/', null, false),
  ('Malacañang Palace', 'malacanang-palace', 'local', 'place', 'Spanish colonial / Republic', 1750, null, true, 'San Miguel, Manila', 'Malacañang Palace (Filipino: Palasyo ng Malakanyang, locally [paˈlɐ̞ʃo näŋ maläkɐˈɲäŋ]), officially known as Malacañan Palace, is the official residence and principal workplace of the president of the Philippines. It is located in the Manila district of San Miguel, along Jose Laurel Street, though it is commonly associated with nearby Mendiola Street. The term Malacañang is often used as a metonym for the Government of the Philippines.', 'Official residence and principal workplace of the President of the Philippines since 1935, and earlier seat of colonial governors.', st_setsrid(st_makepoint(120.9945, 14.5939), 4326)::geography, null, 'exact', null, 'https://www.wikidata.org/wiki/Q942688', null, false),
  ('University of Santo Tomas', 'university-of-santo-tomas', 'local', 'place', 'Spanish colonial', 1611, null, false, 'Sampaloc, Manila', 'The University of Santo Tomas (UST; Filipino: Unibersidad ng Santo Tomás), officially the Pontifical and Royal University of Santo Tomas, The Catholic University of the Philippines or colloquially as Ustê (pronounced [usˈtɛʔ]), is a private Catholic research university in Manila, Philippines.', 'Founded in 1611, the oldest extant university charter in Asia; its Sampaloc campus also served as an internment camp during World War II.', st_setsrid(st_makepoint(120.9897, 14.6097), 4326)::geography, null, 'area_centroid', null, 'https://www.ust.edu.ph/', null, false),
  ('Quiapo Church', 'quiapo-church', 'local', 'place', 'Spanish colonial', 1588, null, true, 'Quiapo, Manila', 'The Minor Basilica and National Shrine of Jesus Nazareno (Filipino: Basilika Menor at Pambansang Dambana ni Jesus Nazareno), commonly known as Quiapo Church (Filipino: Simbahan ng Quiapo) and canonically as the Parish of Saint John the Baptist (Filipino: Parokya ng San Juan Bautista), is a Catholic basilica and national shrine located in the district of Quiapo in Manila, Philippines.', 'Minor Basilica and National Shrine housing the Jesús Nazareno (Black Nazarene), central to annual Manila devotional processions.', st_setsrid(st_makepoint(120.9838, 14.5988), 4326)::geography, null, 'exact', null, 'https://www.wikidata.org/wiki/Q1899439', null, false),
  ('Binondo', 'binondo', 'local', 'place', 'Spanish colonial', 1594, null, false, 'Binondo, Manila', 'Binondo (Chinese: 岷倫洛; pinyin: Mínlúnluò; Pe̍h-ōe-jī: Bîn-lûn-lo̍h; Tagalog: Distrito ng Binondo) is a district in Manila and is referred to as the city''s Chinatown. Its influence extends beyond to the places of Quiapo, Santa Cruz, San Nicolas and Tondo.', 'Established in 1594 across the Pasig River from Intramuros; recognized as the oldest Chinatown in the world.', st_setsrid(st_makepoint(120.967, 14.6), 4326)::geography, null, 'area_centroid', null, 'https://www.wikidata.org/wiki/Q1903520', null, false),
  ('Corregidor Island', 'corregidor-island', 'local', 'place', 'Spanish colonial / World War II', null, null, false, 'Manila Bay, Cavite', 'Corregidor (Tagalog: [ko.ɾɛ.hɪˈdoɾ], Spanish: [ko.re.xiˈðoɾ], Tagalog: Pulo ng Corregidor, Spanish: Isla del Corregidor) is an island located at the entrance of Manila Bay in the southwestern part of Luzon in the Philippines, and is considered part of Cavite City in the province of Cavite despite being closer to Maragondon and Bataan.', 'Strategic fortified island guarding Manila Bay and site of the 1942 Battle of Corregidor.', st_setsrid(st_makepoint(120.5731, 14.3856), 4326)::geography, null, 'area_centroid', null, 'https://www.wikidata.org/wiki/Q928075', null, false),
  ('Barasoain Church', 'barasoain-church', 'local', 'place', 'Philippine Revolution', 1888, null, false, 'Malolos, Bulacan', 'Our Lady of Mount Carmel Parish, also known as Barásoain Church (Tagalog: [baɾaswaˈʔin]; Spanish: [baˈɾa.so.ãĩn]), is a Roman Catholic church built in 1888 in Malolos, Bulacán, Philippines. It is under the jurisdiction of the Diocese of Malolos and is about 42 kilometers (26 mi) from Manila.', 'Site of the 1898 Malolos Congress, drafting of the Malolos Constitution, and inauguration of the First Philippine Republic in 1899.', st_setsrid(st_makepoint(120.8123, 14.8464), 4326)::geography, null, 'exact', null, 'https://www.wikidata.org/wiki/Q4858463', null, false),
  ('Historic City of Vigan', 'historic-city-of-vigan', 'local', 'place', 'Spanish colonial', 1572, null, false, 'Vigan, Ilocos Sur', 'Established in the 16th century, Vigan is the best-preserved example of a planned Spanish colonial town in Asia. Its architecture reflects the coming together of cultural elements from elsewhere in the Philippines, from China and from Europe, resulting in a culture and townscape that have no parallel anywhere in East and South-East Asia.', 'UNESCO World Heritage Site preserving an intact 16th-century Spanish colonial town plan blending Asian and European building traditions. UNESCO World Heritage criteria (ii)(iv) (inscribed 1999): Brief synthesis Vigan is the most intact example in Asia of a planned Spanish colonial town, established in the 16th century.', st_setsrid(st_makepoint(120.3869, 17.5747), 4326)::geography, null, 'area_centroid', null, 'https://data.unesco.org/explore/dataset/whc001/?q=502', null, false),
  ('Paoay Church', 'paoay-church', 'local', 'place', 'Spanish colonial', 1710, null, false, 'Paoay, Ilocos Norte', 'Saint Augustine Parish Church, commonly known as Paoay Church, is a Roman Catholic church in the municipality of Paoay, Ilocos Norte in the Philippines. It is under the ecclesiastical jurisdiction of the Diocese of Laoag. Completed in 1710, the church is famous for its distinctive architecture, a highlight of which are the enormous buttresses on the sides and the back of the building.', 'Earthquake Baroque church completed in 1710 with massive coral-stone buttresses; part of the Baroque Churches of the Philippines UNESCO site. UNESCO World Heritage criteria (ii)(iv) (inscribed 1993): Brief synthesis The Baroque Churches of the Philippines is a serial inscription consisting of four Roman Catholic churches constructed between the 16thand the18th centuries in the Spanish period of the Philippines.', st_setsrid(st_makepoint(120.5216, 18.0615), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=677', null, false),
  ('Miagao Church', 'miagao-church', 'local', 'place', 'Spanish colonial', 1787, 1797, true, 'Miagao, Iloilo', 'Santo Tomás de Villanueva Parish Church, commonly known as Miagao Church, is a Roman Catholic church located in Miagao, Iloilo, Philippines. It is under the jurisdiction of the Archdiocese of Jaro.', 'Fortress-Baroque church carved from yellowish-ochre sandstone with indigenous botanical relief; part of the Baroque Churches of the Philippines UNESCO site. UNESCO World Heritage criteria (ii)(iv) (inscribed 1993): Brief synthesis The Baroque Churches of the Philippines is a serial inscription consisting of four Roman Catholic churches constructed between the 16thand the18th centuries in the Spanish period of the Philippines.', st_setsrid(st_makepoint(122.2355, 10.6419), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=677', null, false),
  ('Banaue Rice Terraces', 'banaue-rice-terraces', 'local', 'place', 'Precolonial', null, null, false, 'Banaue, Ifugao', 'The Banaue Rice Terraces (Filipino: Hagdan-hagdang Palayan ng Banawe) [bɐˈnawe] are terraces that were carved into the mountains of Banaue, Ifugao, in the Philippines, by the ancestors of the Igorot people. The terraces were built with minimal equipment, largely by hand. The terraces are located approximately 1,500 meters (4,900 feet) above sea level. These are fed by an ancient irrigation system from the rainforests above the terraces.', 'A living agricultural landscape in the Cordillera mountains of Ifugao, including the neighboring Batad and Bangaan terrace clusters. UNESCO World Heritage criteria (iii)(iv)(v) (inscribed 1995): Brief synthesis The Rice Terraces of the Philippine Cordilleras is an outstanding example of an evolved, living cultural landscape that can be traced as far back as two millennia ago in the pre-colonial Philippines.', st_setsrid(st_makepoint(121.0667, 16.9333), 4326)::geography, null, 'area_centroid', null, 'https://data.unesco.org/explore/dataset/whc001/?q=722', null, false),
  ('Tabon Caves', 'tabon-caves', 'local', 'place', 'Prehistoric / Paleolithic to Metal Age', null, null, true, 'Quezon, Palawan', 'The Tabon Caves is a cave system located in Lipuun Point, Panitian, Quezon, Palawan in the Philippines. Dubbed as the country''s "cradle of civilization", it is a site of archaeological importance due to the number of jar burials and prehistoric human remains found starting from the 1960s, most notably the Tabon Man.', 'Archaeological cave complex at Lipuun Point yielding Upper Paleolithic Tabon Man fossils and the Neolithic Manunggul burial jar.', st_setsrid(st_makepoint(117.9814, 9.2799), 4326)::geography, null, 'exact', null, 'https://www.nationalmuseum.gov.ph/our-museums/regional-area-and-site-museums/tabon-cave-complex/', null, false),
  ('Chocolate Hills', 'chocolate-hills', 'local', 'place', 'Natural heritage', null, null, false, 'Carmen, Bohol', 'The Chocolate Hills (Cebuano: Mga Bungtod sa Tsokolate, Filipino: Mga Tsokolateng Burol, or Mga Burol na Tsokolate) are a geological formation in the Philippine province of Bohol. A minimum of 1,260 hills, and possibly over 1,776, spread over an area of more than 50 square kilometers (20 sq mi). They are covered in green grass that turns a chocolate-brown during the dry season, hence the name.', 'National Geological Monument of more than 1,260 conical karst limestone hills across central Bohol.', st_setsrid(st_makepoint(124.1667, 9.9167), 4326)::geography, null, 'area_centroid', null, 'https://www.wikidata.org/wiki/Q977422', null, false),
  ('Magellan''s Cross Pavilion', 'magellans-cross-pavilion', 'local', 'place', 'Early colonial', 1521, null, false, 'Cebu City, Cebu', 'Magellan''s Cross Pavilion is a stone kiosk in Cebu City, Philippines. The structure is situated on Plaza Sugbo beside the Basilica del Santo Niño. It houses a Christian cross that was planted by explorers of the Spanish expedition of the first circumnavigation of the world, led by Ferdinand Magellan, upon arriving in Cebu in the Philippines on April 21, 1521.', 'Marks the 1521 arrival of the Magellan expedition in Cebu.', st_setsrid(st_makepoint(123.902, 10.2935), 4326)::geography, null, 'exact', null, 'https://www.wikidata.org/wiki/Q107462441', null, false),
  ('Basilica del Santo Niño', 'basilica-del-santo-nino', 'local', 'place', 'Spanish colonial', 1565, null, false, 'Cebu City, Cebu', 'The Basílica Minore del Santo Niño de Cebú, or simply the Santo Niño Basilica, is a Catholic minor basilica in Cebu City, Philippines. It was originally founded by Augustinian friars Andrés de Urdaneta and Diego de Herrera in 1565.', 'Oldest Roman Catholic church in the Philippines, founded in 1565 where the image of the Santo Niño de Cebú was rediscovered.', st_setsrid(st_makepoint(123.9014, 10.2939), 4326)::geography, null, 'exact', null, 'https://www.wikidata.org/wiki/Q666552', null, false),
  ('Fort San Pedro', 'fort-san-pedro', 'local', 'place', 'Spanish colonial', 1565, null, false, 'Cebu City, Cebu', 'Fort San Pedro (Spanish: Fuerte de San Pedro; Filipino: Moog ng San Pedro) is a military defense structure in Cebu, Philippines, built by the Spanish under the command of Miguel López de Legazpi, first governor of the Captaincy General of the Philippines. It is located in the area now called Plaza Independencia, in the pier area of the city. The original fort was made of wood and built after the arrival of Legazpi and his expedition.', 'Oldest triangular bastion fort in the Philippines, originally founded in 1565 under Miguel López de Legazpi and rebuilt in stone in 1738.', st_setsrid(st_makepoint(123.9058, 10.2922), 4326)::geography, null, 'exact', null, 'https://www.wikidata.org/wiki/Q1472845', null, false),
  ('Aguinaldo Shrine', 'aguinaldo-shrine', 'local', 'place', 'Philippine Revolution', 1898, null, false, 'Kawit, Cavite', 'The Emilio Aguinaldo Shrine (or the Cavite El Viejo Shrine) is a national shrine located in Kawit, Cavite in the Philippines, where the Philippine Declaration of Independence from Spain was declared on June 12, 1898, or Independence Day. To commemorate the event, now known as Araw ng Kalayaan or Independence Day, a national holiday, the Philippine flag is raised here by top government officials on June 12 each year.', 'Ancestral house of Emilio Aguinaldo where Philippine Independence from Spain was proclaimed on June 12, 1898.', st_setsrid(st_makepoint(120.9069, 14.445), 4326)::geography, null, 'exact', null, 'https://www.wikidata.org/wiki/Q3550173', null, false),
  ('Rizal Shrine (Dapitan)', 'rizal-shrine-dapitan', 'local', 'place', 'Late Spanish colonial', 1892, 1896, false, 'Dapitan, Zamboanga del Norte', 'The José Rizal Memorial Protected Landscape, also known as the Rizal Park and Shrine, is a protected landscape and memorial to the Philippines'' national hero located in the city of Dapitan on the island of Mindanao. It preserves the farm site in barrio Talisay where José Rizal was exiled for four years from 1892-1896 after being accused of sedition and plotting the Philippine revolution in Manila by the Spanish colonial authorities.', 'Estate in Talisay where José Rizal lived in exile from 1892 to 1896, establishing a school, clinic, and waterworks.', st_setsrid(st_makepoint(123.4167, 8.6672), 4326)::geography, null, 'exact', null, 'https://www.wikidata.org/wiki/Q1704121', null, false),
  ('National Museum of Fine Arts', 'national-museum-of-fine-arts', 'local', 'place', 'American period / 20th century', 1926, null, false, 'Ermita, Manila', 'The National Museum of Fine Arts is home to 29 galleries and hallway exhibitions comprising of 19 th century Filipino masters, National Artists, leading modern painters, sculptors, and printmakers. Also on view are art loans from other government institutions, organizations, and individuals. Along Padre Burgos Street heading southwest, the monumental Old Legislative Building is presently the National Museum of Fine Arts.', 'Neoclassical former Legislative Building (completed 1926) now housing Juan Luna''s Spoliarium and Philippine fine arts.', st_setsrid(st_makepoint(120.9812, 14.5869), 4326)::geography, null, 'exact', null, 'https://www.nationalmuseum.gov.ph/our-museums/national-museum-of-fine-arts/', null, false),
  ('National Museum of Anthropology', 'national-museum-of-anthropology', 'local', 'place', '20th century', 1940, null, true, 'Rizal Park, Manila', 'The National Museum of Anthropology stages the Philippine ethnographic and terrestrial and underwater archaeological collections narrating the story of the Philippines from the past, as presented through artifacts as evidences of its pre-history. In last days of the Second World War’s Battle of Manila, the Department of Finance Building along with the Legislative Building served as part of the Japanese defensive installations.', 'Repository for national archaeological treasures including the Manunggul Jar, Laguna Copperplate Inscription, and San Diego shipwreck artifacts.', st_setsrid(st_makepoint(120.9808, 14.5853), 4326)::geography, null, 'exact', null, 'https://www.nationalmuseum.gov.ph/our-museums/national-museum-of-anthropology/', null, false),
  ('Spoliarium', 'spoliarium', 'local', 'artifact', 'Late 19th century', 1884, null, false, 'Painted in Rome; held in Manila', 'This hall houses one of the country''s most well-known paintings, the Spoliarium by Juan Luna y Novicio (1857-1899). Displayed across it is El Asesinato del Gobernador Bustamante (The Assassination of Governor Bustamante), the largest known work by another Filipino master painter, Felix Resurrección Hildago (1855-1913), Luna''s contemporary and friend.', 'Gold-medal canvas by Juan Luna at the 1884 Exposición Nacional de Bellas Artes in Madrid, now the centerpiece of the National Museum of Fine Arts.', st_setsrid(st_makepoint(12.4964, 41.9028), 4326)::geography, st_setsrid(st_makepoint(120.9812, 14.5869), 4326)::geography, 'area_centroid', 'exact', 'https://www.wikidata.org/wiki/Q3348220', 'https://www.nationalmuseum.gov.ph/exhibitions/fine-arts/gallery-spoliarium-hall/', false),
  ('Manunggul Jar', 'manunggul-jar', 'local', 'artifact', 'Late Neolithic', -889, -709, true, 'Excavated at Tabon Caves, Palawan; held in Manila', 'The Manunggul Jar is a secondary burial jar excavated from a Neolithic burial site in the Manunggul cave of the Tabon Caves at Lipuun Point in Palawan, Philippines. It dates from 890–710 B.C. and the two figures at the top handle of its cover represent the journey of the soul to the afterlife.', 'National Cultural Treasure depicting two figures sailing to the afterlife; a masterwork of precolonial Philippine pottery.', st_setsrid(st_makepoint(117.9814, 9.2799), 4326)::geography, st_setsrid(st_makepoint(120.9808, 14.5853), 4326)::geography, 'exact', 'exact', 'https://www.wikidata.org/wiki/Q6753165', 'https://www.nationalmuseum.gov.ph/our-collections/archaeology/burial-jars/', false),
  ('Laguna Copperplate Inscription', 'laguna-copperplate-inscription', 'local', 'artifact', 'Precolonial / Shaka 822', 900, null, false, 'Found in Lumban, Laguna; held in Manila', 'The Laguna Copperplate Inscription is an official acquittance (debt relief) certificate inscribed onto a copper plate in the Shaka year 822 (900 A.D.). It is the oldest extant document found in the Philippines. The plate was unearthed in 1987 by a laborer near the mouth of the Lumbang River in Wawa, Lumban, Laguna, in the Philippines during a dredging operation.', 'Oldest known written document found in the Philippines (dated 900 CE in Kawi script), recording debt acquittal and early Luzon-Java ties.', st_setsrid(st_makepoint(121.459, 14.297), 4326)::geography, st_setsrid(st_makepoint(120.9808, 14.5853), 4326)::geography, 'approximate', 'exact', 'https://www.wikidata.org/wiki/Q1463293', 'https://www.nationalmuseum.gov.ph/2022/09/20/the-9th-to-10th-century-archaeological-evidence-of-maritime-relations-between-the-philippines-and-the-islands-of-southeast-asia/', false),
  ('Golden Tara of Agusan', 'golden-tara-of-agusan', 'local', 'artifact', 'Precolonial / Butuan polity', 850, 950, true, 'Found near Esperanza, Agusan del Sur; held in Chicago', 'The Agusan image (commonly referred to in the Philippines as the Golden Tara due to its earliest and most-common association with, but disputed, identity as an image of a Buddhist Tara) is a 2 kg (4.4 lb), 21-karat gold statuette found in 1917 on the banks of the Wawa River near Esperanza, Agusan del Sur, Mindanao in the Philippines. It is dated to the 9th–10th centuries.', '21-karat solid gold statuette demonstrating precolonial Hindu-Buddhist metallurgy and maritime trade in Mindanao.', st_setsrid(st_makepoint(125.65, 8.68), 4326)::geography, st_setsrid(st_makepoint(-87.6169, 41.8661), 4326)::geography, 'approximate', 'exact', 'https://www.wikidata.org/wiki/Q33159150', 'https://www.fieldmuseum.org/', false),
  ('Balangay (Butuan Boats)', 'balangay-butuan-boats', 'local', 'artifact', 'Precolonial / Maritime Southeast Asia', 689, 988, true, 'Butuan, Agusan del Norte', 'A balangay, or barangay, is a type of lashed-lug boat built by joining planks edge-to-edge using pins, dowels, and fiber lashings. They are found throughout the Philippines and were used largely as trading ships up until the colonial era. The oldest known balangay are the eleven Butuan boats, which have been carbon-dated individually from 689 to 988 CE and were recovered from several sites in Butuan, Agusan del Norte.', 'Oldest excavated watercraft in the Philippines (radiocarbon-dated 689–988 CE), demonstrating plank-built ocean navigation before European contact.', st_setsrid(st_makepoint(125.543, 8.948), 4326)::geography, null, 'area_centroid', null, 'https://www.nationalmuseum.gov.ph/exhibitions/nmp-butuan/butuan-boat-site-museum/', null, false),
  ('Boxer Codex', 'boxer-codex', 'local', 'artifact', 'Early Spanish colonial', 1590, null, true, 'Compiled in Manila; held in Bloomington, Indiana', 'The Boxer Codex is a late-16th-century Spanish manuscript produced in the Philippines. It contains 75 colored illustrations of the peoples of China, the Philippines, Japan, Java, the Moluccas, the Ladrones, and Siam. About 270 pages of Spanish text describe these places, their inhabitants and customs.', '1590 illustrated manuscript documenting dress, society, and beliefs across the Philippines and maritime East and Southeast Asia.', st_setsrid(st_makepoint(120.9736, 14.5939), 4326)::geography, st_setsrid(st_makepoint(-86.5189, 39.1678), 4326)::geography, 'area_centroid', 'exact', 'https://www.wikidata.org/wiki/Q3701552', 'https://webapp1.dlib.indiana.edu/metsnav3/general/index.html#mets=http%3A%2F%2Fpurl.dlib.indiana.edu%2Fiudl%2Fgeneral%2Fmets%2FVAB8326', false),
  ('Doctrina Christiana', 'doctrina-christiana', 'local', 'artifact', 'Early Spanish colonial', 1593, null, false, 'Printed in Manila; held in Washington, D.C.', 'The Doctrina Christiana (Christian Doctrine) were two early books on the catechism of the Catholic Church, both published 1593 in Manila, Philippines. These are two of the earliest printed books in the Philippines. The Doctrina Christiana en letra y lengua China (1593-1605), by Fray Juan Cobo and Fray Miguel de Benavides, printed by the Sangley Chinese printer Keng Yong.', 'Among the earliest surviving woodblock books printed in the Philippines (1593), preserving early Tagalog in Latin and Baybayin scripts.', st_setsrid(st_makepoint(120.967, 14.6), 4326)::geography, st_setsrid(st_makepoint(-77.0047, 38.8886), 4326)::geography, 'area_centroid', 'exact', 'https://www.wikidata.org/wiki/Q2576737', 'https://www.wikidata.org/wiki/Q131454', false),
  ('Bells of Balangiga', 'bells-of-balangiga', 'local', 'artifact', 'Spanish colonial / Philippine–American War', 1863, null, true, 'Balangiga, Eastern Samar (held in Wyoming 1901–2018; returned 2018)', 'The Balangiga bells (Spanish: Campanas de Balangiga; Tagalog: Mga Batingaw ng Balangiga; Waray: Lingganay han Balangiga) are three church bells that were taken by the United States Army from the Church of San Lorenzo de Martir in Balangiga, Eastern Samar, Philippines, as war trophies after reprisals following the Balangiga massacre in 1901 during the Philippine–American War.', 'Three parish church bells seized by U.S. forces in 1901 after the Balangiga conflict and formally repatriated to Balangiga Church in December 2018.', st_setsrid(st_makepoint(125.3853, 11.1095), 4326)::geography, null, 'exact', null, 'https://www.wikidata.org/wiki/Q4850035', null, false),
  ('Noli Me Tángere Original Manuscript', 'noli-me-tangere-manuscript', 'local', 'artifact', 'Late Spanish colonial / Propaganda Movement', 1887, null, false, 'Published in Berlin; held in Manila', 'Noli Me Tángere (Latin for "Touch Me Not") is a novel by Filipino writer and activist José Rizal and was published during the Spanish colonial period of the Philippines. It explores inequities in law and practice in terms of the treatment by the ruling government and the Spanish Catholic friars of the resident peoples in the late 19th century.', 'José Rizal''s 1887 reformist novel manuscript, instrumental to Philippine nationalist consciousness and preserved at the National Library.', st_setsrid(st_makepoint(13.405, 52.52), 4326)::geography, st_setsrid(st_makepoint(120.981, 14.582), 4326)::geography, 'area_centroid', 'exact', 'https://www.wikidata.org/wiki/Q568299', 'https://web.nlp.gov.ph/', false),
  ('San Diego Galleon Artifacts', 'san-diego-galleon-artifacts', 'local', 'artifact', 'Early Spanish colonial', 1600, null, false, 'Sunk off Fortune Island, Nasugbu; held in Manila', 'The galleon San Diego was built as the trading ship San Antonio before hastily being converted into a warship of the Spanish Navy. On December 14, 1600, the fully laden San Diego was engaged by the Dutch warship Mauritius under the command of Admiral Olivier van Noort a short distance away from Fortune Island, Nasugbu, Philippines.', 'Cargo, navigational instruments, Ming porcelain, and weaponry recovered from the Spanish galleon San Diego, sunk in 1600 off Nasugbu.', st_setsrid(st_makepoint(120.492, 14.056), 4326)::geography, st_setsrid(st_makepoint(120.9808, 14.5853), 4326)::geography, 'approximate', 'exact', 'https://www.wikidata.org/wiki/Q499961', 'https://www.nationalmuseum.gov.ph/2021/12/27/kraak-porcelain-from-san-diego-shipwreck/', false),
  ('Stonehenge', 'stonehenge', 'international', 'place', 'Neolithic / Bronze Age', -3000, -1500, true, 'Wiltshire, England', 'Stonehenge and Avebury, in Wiltshire, are among the most famous groups of megaliths in the world. The two sanctuaries consist of circles of menhirs arranged in a pattern whose astronomical significance is still being explored. These holy places and the nearby Neolithic sites are an incomparable testimony to prehistoric times.', 'Prehistoric megalithic stone circle on Salisbury Plain, part of a UNESCO World Heritage ceremonial landscape. UNESCO World Heritage criteria (i)(ii)(iii) (inscribed 1986): Brief synthesis The World Heritage property Stonehenge, Avebury and Associated Sites is internationally important for its complexes of outstanding prehistoric monuments.', st_setsrid(st_makepoint(-1.8262, 51.1789), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=373', null, false),
  ('Angkor Wat', 'angkor-wat', 'international', 'place', 'Khmer Empire', 1100, null, true, 'Siem Reap, Cambodia', 'Angkor is one of the most important archaeological sites in South-East Asia. Stretching over some 400 km2, including forested area, Angkor Archaeological Park contains the magnificent remains of the different capitals of the Khmer Empire, from the 9th to the 15th century. They include the famous Temple of Angkor Wat and, at Angkor Thom, the Bayon Temple with its countless sculptural decorations.', 'Monumental 12th-century temple complex of the Khmer Empire and the largest religious structure in the world by land area. UNESCO World Heritage criteria (i)(ii)(iii)(iv) (inscribed 1992): Brief synthesis Angkor, in Cambodia’s northern province of Siem Reap, is one of the most important archaeological sites of Southeast Asia.', st_setsrid(st_makepoint(103.867, 13.4125), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=668', null, false),
  ('Machu Picchu', 'machu-picchu', 'international', 'place', 'Inca', 1450, null, true, 'Cusco region, Peru', 'Machu Picchu stands 2,430 m above sea-level, in the middle of a tropical mountain forest, in an extraordinarily beautiful setting. It was probably the most amazing urban creation of the Inca Empire at its height; its giant walls, terraces and ramps seem as if they have been cut naturally in the continuous rock escarpments.', 'High-altitude 15th-century Inca citadel in the eastern Peruvian Andes and a UNESCO World Heritage Site. UNESCO World Heritage criteria (i)(iii)(vii)(ix) (inscribed 1983): Brief Synthesis Embedded within a dramatic landscape at the meeting point between the Peruvian Andes and the Amazon Basin, the Historic Sanctuary of Machu Picchu is among the greatest artistic, architectural and land use achievements anywhere and the most…', st_setsrid(st_makepoint(-72.545, -13.1631), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=274', null, false),
  ('Great Pyramid of Giza', 'great-pyramid-of-giza', 'international', 'place', 'Old Kingdom Egypt', -2599, null, true, 'Giza, Egypt', 'The Great Pyramid of Giza is the largest of the Egyptian pyramids and the most famous landmark of the Giza pyramid complex in Giza, Egypt. It is the oldest of the Seven Wonders of the Ancient World, and the only wonder that has remained largely intact. The Great Pyramid served as the tomb of Egyptian Pharaoh Khufu ("Cheops"), who ruled during the Fourth Dynasty of the Old Kingdom. It was built c. 2600 BC over a period of about 26 years.', 'Oldest and only surviving Wonder of the Ancient World, constructed c. 2600 BCE for Pharaoh Khufu. UNESCO World Heritage criteria (i)(iii) (inscribed 1979): Brief Synthesis Memphis is located in the center of the floodplain of the western side of the Nile. Its fame comes from its being the first Capital of Ancient Egypt.', st_setsrid(st_makepoint(31.1342, 29.9792), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=86', null, false),
  ('Colosseum', 'colosseum', 'international', 'place', 'Roman Empire / Flavian dynasty', 72, 80, false, 'Rome, Italy', 'The Colosseum (KOL-ə-SEE-əm; Italian: Colosseo [kolosˈsɛːo]) is an elliptical amphitheatre in the centre of the city of Rome, Italy, just east of the Roman Forum. It is the largest ancient amphitheatre ever built, and is the largest standing amphitheatre in the world. Construction began under Emperor Vespasian (r. 69–79 AD) in 72 and was completed in AD 80 under his successor and heir, Titus (r. 79–81).', 'Largest ancient amphitheatre ever constructed (72–80 CE) and enduring landmark of Imperial Rome. UNESCO World Heritage criteria (i)(ii)(iii)(iv) (inscribed 1980): Brief synthesis The World Heritage property encompasses the whole historic centre of Rome within the city walls at their widest extent in the 17th century, as well as the Basilica of St. Paul’s Outside the Walls.', st_setsrid(st_makepoint(12.4922, 41.8903), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=91', null, false),
  ('Acropolis of Athens', 'acropolis-of-athens', 'international', 'place', 'Classical Greece', -446, -431, true, 'Athens, Greece', 'The Acropolis of Athens and its monuments are universal symbols of the classical spirit and civilization and form the greatest architectural and artistic complex bequeathed by Greek Antiquity to the world. In the second half of the fifth century bc, Athens, following the victory against the Persians and the establishment of democracy, took a leading position amongst the other city-states of the ancient world.', 'Citadel of Classical Athens housing the Parthenon, Erechtheion, and Propylaea, UNESCO World Heritage Site. UNESCO World Heritage criteria (i)(ii)(iii)(iv) (inscribed 1987): Brief synthesis The Acropolis of Athens is the most striking and complete ancient Greek monumental complex still existing in our times. It is situated on a hill of average height (156m) that rises in the basin of Athens.', st_setsrid(st_makepoint(23.7261, 37.9717), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=404', null, false),
  ('Taj Mahal', 'taj-mahal', 'international', 'place', 'Mughal Empire', 1631, 1653, true, 'Agra, Uttar Pradesh, India', 'An immense mausoleum of white marble, built in Agra between 1631 and 1648 by order of the Mughal emperor Shah Jahan in memory of his favourite wife, the Taj Mahal is the jewel of Muslim art in India and one of the universally admired masterpieces of the world''s heritage.', 'Ivory-white marble mausoleum commissioned in 1631 by Emperor Shah Jahan, synthesizing Persian, Islamic, and Indian architecture. UNESCO World Heritage criteria (i) (inscribed 1983): Brief synthesis The Taj Mahal is located on the right bank of the Yamuna River in a vast Mughal garden that encompasses nearly 17 hectares, in the Agra District in Uttar Pradesh.', st_setsrid(st_makepoint(78.0419, 27.175), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=252', null, false),
  ('Alhambra', 'alhambra', 'international', 'place', 'Nasrid Kingdom of Granada', 1238, null, false, 'Granada, Spain', 'Rising above the modern lower town, the Alhambra and the Albaycín, situated on two adjacent hills, form the medieval part of Granada. To the east of the Alhambra fortress and residence are the magnificent gardens of the Generalife, the former rural residence of the emirs who ruled this part of Spain in the 13th and 14th centuries.', 'Nasrid palace and fortress complex begun in 1238, celebrated as the pinnacle of Moorish architecture in Iberia. UNESCO World Heritage criteria (i)(iii)(iv) (inscribed 1984): Brief synthesis The property of the Alhambra, Generalife and Albayzín, Granada, stands on two adjacent hills, separated by the river Darro.', st_setsrid(st_makepoint(-3.59, 37.1775), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=314', null, false),
  ('Forbidden City', 'forbidden-city', 'international', 'place', 'Ming and Qing dynasties', 1406, 1420, false, 'Beijing, China', 'Seat of supreme power for over five centuries (1416-1911), the Forbidden City in Beijing, with its landscaped gardens and many buildings (whose nearly 10,000 rooms contain furniture and works of art), constitutes a priceless testimony to Chinese civilization during the Ming and Qing dynasties. The Imperial Palace of the Qing Dynasty in Shenyang consists of 114 buildings constructed between 1625–26 and 1783.', 'Imperial palace complex at the heart of Beijing that served Ming and Qing emperors from 1420 to 1924. UNESCO World Heritage criteria (i)(ii)(iii)(iv) (inscribed 1987): Brief synthesis As the royal residences of the emperors of the Ming and Qing dynasties from the 15th to 20th century, the Imperial Palaces of the Ming and Qing dynasties in Beijing and Shenyang were the centre of State power in late feudal China.', st_setsrid(st_makepoint(116.3908, 39.9158), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=439', null, false),
  ('Petra', 'petra', 'international', 'place', 'Nabataean Kingdom', -311, null, true, 'Ma''an Governorate, Jordan', 'Inhabited since prehistoric times, this Nabataean caravan-city, situated between the Red Sea and the Dead Sea, was an important crossroads between Arabia, Egypt and Syria-Phoenicia. Petra is half-built, half-carved into the rock, and is surrounded by mountains riddled with passages and gorges. It is one of the world''s most famous archaeological sites, where ancient Eastern traditions blend with Hellenistic architecture.', 'Caravan capital of the Nabataean Kingdom famed for rock-cut sandstone facades and water conduit engineering. UNESCO World Heritage criteria (i)(iii)(iv) (inscribed 1985): Brief synthesis Situated between the Red Sea and the Dead Sea and inhabited since prehistoric times, the rock-cut capital city of the Nabateans, became during Hellenistic and Roman times a major caravan centre for the incense of Arabia, the silks of China…', st_setsrid(st_makepoint(35.4403, 30.3289), 4326)::geography, null, 'area_centroid', null, 'https://data.unesco.org/explore/dataset/whc001/?q=326', null, false),
  ('Borobudur', 'borobudur', 'international', 'place', 'Shailendra dynasty / 9th century', 800, null, true, 'Magelang, Central Java, Indonesia', 'This famous Buddhist temple, dating from the 8th and 9th centuries, is located in central Java. It was built in three tiers: a pyramidal base with five concentric square terraces, the trunk of a cone with three circular platforms and, at the top, a monumental stupa. The walls and balustrades are decorated with fine low reliefs, covering a total surface area of 2,500 m2.', 'World''s largest Buddhist temple, built in the 9th century with nine stacked platforms and 2,672 narrative relief panels. UNESCO World Heritage criteria (i)(ii) (inscribed 1991): Brief synthesis The Borobudur Temple Compounds is one of the greatest Buddhist monuments in the world, and was built in the 8th and 9th centuries AD during the reign of the Syailendra Dynasty.', st_setsrid(st_makepoint(110.204, -7.608), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=592', null, false),
  ('Hagia Sophia', 'hagia-sophia', 'international', 'place', 'Byzantine / Ottoman', 532, 537, false, 'Istanbul, Turkey', 'Hagia Sophia, officially the Hagia Sophia Grand Mosque, is a mosque and a major cultural and historical site in Istanbul, Turkey. It was formerly a church (360–1453) and a museum (1935–2020). The last of three church buildings to be successively erected on the site by the Eastern Roman Empire, it was completed in AD 537, becoming the world''s largest interior space and among the first to employ a fully pendentive dome.', 'Completed in 537 CE under Emperor Justinian I as a Byzantine cathedral with a monumental pendentive dome, later an Ottoman imperial mosque. UNESCO World Heritage criteria (i)(ii)(iii)(iv) (inscribed 1985): Brief synthesis Strategically located on the Bosphorus peninsula between the Balkans and Anatolia, the Black Sea and the Mediterranean, Istanbul was successively the capital of the Eastern Roman Empire, and the Ottoman Empire and has been associated with…', st_setsrid(st_makepoint(28.98, 41.0083), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=356', null, false),
  ('Pompeii', 'pompeii', 'international', 'place', 'Roman Antiquity', -599, 79, true, 'Campania, Italy', 'When Vesuvius erupted on 24 August AD 79, it engulfed the two flourishing Roman towns of Pompei and Herculaneum, as well as the many wealthy villas in the area. These have been progressively excavated and made accessible to the public since the mid-18th century.', 'Roman city preserved beneath volcanic ash during the 79 CE eruption of Mount Vesuvius, offering a detailed record of Roman urban life. UNESCO World Heritage criteria (iii)(iv)(v) (inscribed 1997): Brief synthesis The World Heritage property includes three different archaeological areas: the ancient towns of Pompeii and Herculaneum together with the Villa of the Mysteries (to the west of Pompeii) and the Villa of the Papyri (to the west of…', st_setsrid(st_makepoint(14.4897, 40.7506), 4326)::geography, null, 'area_centroid', null, 'https://data.unesco.org/explore/dataset/whc001/?q=829', null, false),
  ('Chichen Itza', 'chichen-itza', 'international', 'place', 'Maya Terminal Classic', 600, 900, true, 'Yucatán, Mexico', 'This sacred site was one of the greatest Mayan centres of the Yucatán peninsula. Throughout its nearly 1,000-year history, different peoples have left their mark on the city. The Maya and Toltec vision of the world and the universe is revealed in their stone monuments and artistic works.', 'Major Maya ceremonial and political centre featuring El Castillo (Temple of Kukulcán) and a UNESCO World Heritage designation. UNESCO World Heritage criteria (i)(ii)(iii) (inscribed 1988): Brief synthesis The town of Chichen-Itza was established during the Classic period close to two natural cavities (cenotes or chenes), which gave the town its name "At the edge of the well of the Itzaes".', st_setsrid(st_makepoint(-88.5686, 20.6831), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=483', null, false),
  ('Rosetta Stone', 'rosetta-stone', 'international', 'artifact', 'Ptolemaic Egypt', -195, null, false, 'Inscribed at Memphis / found at Rashid; held in London', 'The Rosetta Stone is a stele of granodiorite inscribed with three versions of a decree issued in 196 BC during the Ptolemaic dynasty of Egypt, on behalf of King Ptolemy V Epiphanes. The top and middle texts are in Ancient Egyptian using hieroglyphic and Demotic scripts, respectively, while the bottom is in Ancient Greek.', 'Trilingual decree of 196 BCE in hieroglyphs, Demotic, and Ancient Greek that unlocked the decipherment of Egyptian hieroglyphs.', st_setsrid(st_makepoint(30.4164, 31.4044), 4326)::geography, st_setsrid(st_makepoint(-0.1269, 51.5194), 4326)::geography, 'approximate', 'exact', 'https://www.wikidata.org/wiki/Q48584', 'https://sketchfab.com/3d-models/the-rosetta-stone-1e03509704a3490e99a173e53b93e282', false),
  ('Parthenon Sculptures', 'parthenon-sculptures', 'international', 'artifact', 'Classical Greece', -446, -431, true, 'Created for the Parthenon, Athens; held in London', 'The Elgin Marbles (EL-ghin) are a collection of Ancient Greek sculptures from the Parthenon and other structures from the Acropolis of Athens, removed from Ottoman Greece in the early 19th century and shipped to Britain by agents of Thomas Bruce, 7th Earl of Elgin, and now held in the British Museum in London. The majority of the sculptures were created in the 5th century BC under the direction of sculptor and architect Phidias.', '5th-century BCE marble friezes and metopes removed from the Acropolis of Athens in the early 19th century and exhibited at the British Museum.', st_setsrid(st_makepoint(23.7266, 37.9715), 4326)::geography, st_setsrid(st_makepoint(-0.1269, 51.5194), 4326)::geography, 'exact', 'exact', 'http://odysseus.culture.gr/h/3/gh351.jsp?obj_id=2384', 'https://www.wikidata.org/wiki/Q6373', false),
  ('Bust of Nefertiti', 'bust-of-nefertiti', 'international', 'artifact', 'New Kingdom Egypt / Amarna Period', -1344, null, true, 'Crafted at Amarna, Egypt; held in Berlin', 'The Nefertiti Bust is a painted stucco-coated limestone bust of Nefertiti, the Great Royal Wife of Egyptian pharaoh Akhenaten. It is on display in the Neues Museum of Berlin. The work is believed to have been crafted in 1345 BC by Thutmose because it was found in his sculpture workshop in Tell-el Amarna, Egypt. It is one of the most-copied works of ancient Egypt.', 'Painted limestone portrait attributed to sculptor Thutmose (c. 1345 BCE), excavated at Tell el-Amarna in 1912 and exhibited in Berlin.', st_setsrid(st_makepoint(30.8964, 27.6453), 4326)::geography, st_setsrid(st_makepoint(13.3978, 52.5206), 4326)::geography, 'approximate', 'exact', 'https://www.wikidata.org/wiki/Q582172', 'https://www.smb.museum/en/museums-institutions/neues-museum/home/', false),
  ('Code of Hammurabi', 'code-of-hammurabi', 'international', 'artifact', 'Old Babylonian Empire', -1752, null, true, 'Excavated at Susa, Iran; held in Paris', 'The Code of Hammurabi is a Babylonian legal text composed c. 1753 BC. It is one of the most recognizable legal texts from the ancient Near East, written in the Old Babylonian dialect of Akkadian, purportedly by Hammurabi, sixth king of the First Dynasty of Babylon. The primary copy of the text is inscribed on a basalt stele 2.25 m (7 ft 4+1⁄2 in) tall. Held at the Musée du Louvre (Richelieu, [AO] Salle 227 - Salle du code d''Hammurabi, Hors vitrine).', 'Basalt stele inscribed in Akkadian cuneiform (c. 1753 BCE) with 282 legal provisions; moved in antiquity from Babylon to Susa and excavated in 1901.', st_setsrid(st_makepoint(48.2578, 32.1906), 4326)::geography, st_setsrid(st_makepoint(2.3358, 48.8611), 4326)::geography, 'approximate', 'exact', 'https://www.wikidata.org/wiki/Q93304', 'https://collections.louvre.fr/en/ark:/53355/cl010174436', false),
  ('Cyrus Cylinder', 'cyrus-cylinder', 'international', 'artifact', 'Achaemenid Empire', -538, null, true, 'Excavated at Babylon, Iraq; held in London', 'The Cyrus Cylinder is an ancient clay cylinder, now broken into several pieces, on which is written an Achaemenid royal inscription in Akkadian cuneiform script in the name of the Persian king Cyrus the Great. It dates from the 6th century BC and was discovered in the ruins of the ancient Mesopotamian city of Babylon (now in modern Iraq) in 1879. It is currently in the possession of the British Museum.', 'Clay cylinder inscribed in Akkadian cuneiform for Cyrus the Great after the 539 BCE conquest of Babylon, unearthed in 1879.', st_setsrid(st_makepoint(44.4211, 32.5425), 4326)::geography, st_setsrid(st_makepoint(-0.1269, 51.5194), 4326)::geography, 'approximate', 'exact', 'https://www.wikidata.org/wiki/Q405008', 'https://www.wikidata.org/wiki/Q6373', false),
  ('Terracotta Army', 'terracotta-army', 'international', 'artifact', 'Qin dynasty', -209, -208, true, 'Lintong, Xi''an, Shaanxi, China', 'The Terracotta Army is a collection of terracotta sculptures depicting the armies of Qin Shi Huang, the first emperor of China. It is a form of funerary art buried with the emperor in 210–209 BCE in his mausoleum with the purpose of protecting him in his afterlife. The figures, dating from approximately the late 200s BCE, were discovered in 1974 by local farmers in Lintong County, outside Xi''an, Shaanxi, China.', 'Thousands of life-sized terracotta warriors buried with Qin Shi Huang (c. 210–209 BCE) and preserved on site at the Mausoleum Museum in Xi''an. UNESCO World Heritage criteria (i)(iii)(iv) (inscribed 1987): Brief synthesis Located at the northern foot of Lishan Mountain, 35 kilometers northeast of Xi''an, Shaanxi Province, Qinshihuang Mausoleum is the tomb of Emperor Qinshihuang, founder of the first unified empire in Chinese history during the 3rd century BCE.', st_setsrid(st_makepoint(109.2731, 34.385), 4326)::geography, null, 'exact', null, 'https://data.unesco.org/explore/dataset/whc001/?q=441', null, false),
  ('Dead Sea Scrolls', 'dead-sea-scrolls', 'international', 'artifact', 'Second Temple period', -299, 100, true, 'Found at Qumran Caves; held in Jerusalem', 'The Dead Sea Scrolls (DSS), which mostly consist of the Qumran Caves Scrolls, are a set of ancient Jewish biblical manuscripts from the Second Temple period. They were discovered over a period of ten years, between 1946 and 1956, at the Qumran Caves near Ein Feshkha in the West Bank, on the northern shore of the Dead Sea and some nearby places.', 'Ancient Jewish biblical and sectarian manuscripts (3rd century BCE – 1st century CE) discovered in the Qumran Caves between 1946 and 1956.', st_setsrid(st_makepoint(35.4586, 31.7408), 4326)::geography, st_setsrid(st_makepoint(35.2028, 31.7733), 4326)::geography, 'approximate', 'exact', 'https://www.wikidata.org/wiki/Q145780', 'https://www.deadseascrolls.org.il/', false)
