insert into public.entry_media (entry_id, image_url, source_url, caption, photo_year, media_period, creator, attribution_text, license, license_url, comparison_group, display_order)
select e.id, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Baluartillo_de_San_Jos%C3%A9%2C_Manila%2C_Filipinas%2C_2023-08-26%2C_DD_41.jpg/960px-Baluartillo_de_San_Jos%C3%A9%2C_Manila%2C_Filipinas%2C_2023-08-26%2C_DD_41.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'https://commons.wikimedia.org/wiki/File:Baluartillo_de_San_Jos%C3%A9%2C_Manila%2C_Filipinas%2C_2023-08-26%2C_DD_41.jpg', 'Baluartillo de San José, Intramuros, Manila (2023).', 2023, 'modern', 'Diego Delso', 'Diego Delso (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'intramuros-compare', 0
from public.entries e
where e.slug = 'intramuros'
  and not exists (
    select 1 from public.entry_media em
    where em.entry_id = e.id and em.image_url = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/Baluartillo_de_San_Jos%C3%A9%2C_Manila%2C_Filipinas%2C_2023-08-26%2C_DD_41.jpg/960px-Baluartillo_de_San_Jos%C3%A9%2C_Manila%2C_Filipinas%2C_2023-08-26%2C_DD_41.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail'
  );

insert into public.entry_media (entry_id, image_url, source_url, caption, photo_year, media_period, creator, attribution_text, license, license_url, comparison_group, display_order)
select e.id, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Manila_Walled_City_Destruction_May_1945.jpg/960px-Manila_Walled_City_Destruction_May_1945.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'https://commons.wikimedia.org/wiki/File:Manila_Walled_City_Destruction_May_1945.jpg', 'Intramuros historic core after the 1945 Battle of Manila.', 1945, 'archival', 'Unknown photographer', 'Illustration 341 in Medical Dept., U.S. Army: Surgery in World War II: Activities of Surgical Consultants, Vol. II , Office of the Surgeon general, Dept. of the Army, Washington, D.C., 1964.', 'Public domain', null, 'intramuros-compare', 1
from public.entries e
where e.slug = 'intramuros'
